import { Group, Mesh, PlaneGeometry, Color, Vector3 } from 'three/webgpu';
import {
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
} from 'three/webgpu';
import { mix, uv, color } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // ----- Helpers -----
  const toColor = (hex) => new Color(hex);
  const lerpColor = (src, dst, t) => src.clone().lerp(dst, t);
  const createGradientMaterial = () => {
    const mat = new MeshPhysicalNodeMaterial();
    // vertical albedo ramp
    const albedoNode = mix(color('#1b1b23'), color('#101015'), uv().y);
    mat.colorNode = albedoNode;
    mat.metalness = 0.5;
    mat.roughness = 0.55;
    mat.clearcoat = 0.2;
    // anisotropy (supported on PhysicalNodeMaterial)
    mat.anisotropy = 0.6;
    mat.clearcoatRoughness = 0.25;
    return mat;
  };

  const createShadowMaterial = () => {
    const mat = new MeshBasicNodeMaterial({ transparent: true });
    mat.color = new Color('#000000');
    mat.opacity = 0.35;
    return mat;
  };

  const createUnderlineMaterial = () => {
    const mat = new MeshStandardNodeMaterial({ emissive: toColor('#ff2a38'), emissiveIntensity: 1.8 });
    mat.metalness = 0;
    mat.roughness = 1;
    return mat;
  };

  // ----- Geometry -----
  const RAIL_WIDTH = 3.6;
  const RAIL_HEIGHT = 0.5;
  const ENTRY_COUNT = 5;
  const ENTRY_SPACING = 0.68; // center distance
  const UNDERLINE_WIDTH = 0.28;
  const UNDERLINE_HEIGHT = 0.025;
  const ENTRY_HIT_WIDTH = 0.6;
  const ENTRY_HIT_HEIGHT = 0.34;

  // ----- Root Group -----
  const root = new Group();
  root.name = 'nav-dock';

  // ----- Shadow Plane -----
  const shadowMat = createShadowMaterial();
  const shadowGeo = new PlaneGeometry(RAIL_WIDTH, RAIL_HEIGHT);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.06, 0); // offset down, behind rail
  root.add(shadowMesh);

  // ----- Rail Plane -----
  const railMat = createGradientMaterial();
  const railGeo = new PlaneGeometry(RAIL_WIDTH, RAIL_HEIGHT);
  const railMesh = new Mesh(railGeo, railMat);
  railMesh.position.set(0, 0, 0.15); // floats above shadow
  root.add(railMesh);

  // ----- Underline Bar -----
  const underlineMat = createUnderlineMaterial();
  const underlineGeo = new PlaneGeometry(UNDERLINE_WIDTH, UNDERLINE_HEIGHT);
  const underlineMesh = new Mesh(underlineGeo, underlineMat);
  underlineMesh.position.set(-ENTRY_SPACING * 2, -0.06, 0.151);
  root.add(underlineMesh);

  // ----- Text Entries -----
  const entries = [];
  const entryPositions = [];
  const timelines = [];

  const textColors = {
    active: '#e8ecf2',
    inactive: '#a6adba',
    hover: '#e8ecf2',
  };

  const items = [
    { text: 'HOME', role: 'nav-active' },
    { text: 'FEATURES', role: 'nav-item' },
    { text: 'COLLECTION', role: 'nav-item' },
    { text: 'PRICING', role: 'nav-item' },
    { text: 'JOURNAL', role: 'nav-item' },
  ];

  items.forEach((item, i) => {
    const isActive = i === 0;
    const cx = -ENTRY_SPACING * 2 + i * ENTRY_SPACING;
    entryPositions.push(cx);

    const entryGroup = new Group();
    entryGroup.position.set(cx, 0, 0.151);
    entryGroup.scale.set(1, 1, 1);
    root.add(entryGroup);

    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: 13,
      color: isActive ? textColors.active : textColors.inactive,
      align: 'center',
    });
    // Center text within its hit area
    txt.position.set(0, 0, 0);
    entryGroup.add(txt);

    const entry = {
      index: i,
      group: entryGroup,
      textObject: txt,
      isActive,
    };
    entries.push(entry);
  });

  // ----- Interaction Handlers -----
  const activateEntry = (newIdx) => {
    const prevActive = entries.find((e) => e.isActive);
    if (prevActive) prevActive.isActive = false;
    const newActive = entries[newIdx];
    newActive.isActive = true;

    // Update text colors
    entries.forEach((e) => {
      const mat = e.textObject.material;
      const targetHex = e.isActive ? textColors.active : textColors.inactive;
      const target = toColor(targetHex);
      const tl = gsap.timeline();
      tl.to(mat.color, {
        r: target.r,
        g: target.g,
        b: target.b,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      timelines.push(tl);
    });

    // Animate underline
    const ulTL = gsap.timeline();
    ulTL.to(
      underlineMesh.position,
      {
        x: entryPositions[newIdx],
        duration: 0.26,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      },
      0
    );
    ulTL.to(
      underlineMesh.scale,
      { x: 1.04, duration: 0.12, ease: 'power4.out' },
      0
    );
    ulTL.to(underlineMesh.scale, { x: 1, duration: 0.12, ease: 'power4.out' }, 0.12);
    timelines.push(ulTL);
  };

  const hoverEntry = (idx) => {
    const entry = entries[idx];
    if (entry.isActive) return;
    const mat = entry.textObject.material;
    const target = toColor(textColors.hover);
    const tl = gsap.timeline();
    tl.to(
      mat.color,
      {
        r: target.r,
        g: target.g,
        b: target.b,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      0
    );
    timelines.push(tl);
  };

  const unhoverEntry = (idx) => {
    const entry = entries[idx];
    if (entry.isActive) return;
    const mat = entry.textObject.material;
    const target = toColor(textColors.inactive);
    const tl = gsap.timeline();
    tl.to(
      mat.color,
      {
        r: target.r,
        g: target.g,
        b: target.b,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      0
    );
    timelines.push(tl);
  };

  const pressEntry = (idx) => {
    const entry = entries[idx];
    const group = entry.group;
    const tl = gsap.timeline();
    tl.to(
      group.scale,
      {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      },
      0
    );
    tl.to(
      group.position,
      {
        z: -0.03,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      },
      0
    );
    timelines.push(tl);
  };

  const releaseEntry = (idx) => {
    const entry = entries[idx];
    const group = entry.group;
    const tl = gsap.timeline();
    tl.to(
      group.scale,
      {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      },
      0
    );
    tl.to(
      group.position,
      {
        z: 0,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      },
      0
    );
    timelines.push(tl);
  };

  // ----- Mount animation -----
  gsap.from(root.position, {
    y: 0.4,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });

  // ----- UserData Handlers -----
  root.userData.handlers = {
    hover: (idx) => hoverEntry(idx),
    unhover: (idx) => unhoverEntry(idx),
    press: (idx) => pressEntry(idx),
    release: (idx) => releaseEntry(idx),
    activate: (idx) => activateEntry(idx),
    navigate: (idx) => {
      const targets = ['hub-home', 'hub-features', 'hub-collection', 'hub-pricing', 'hub-journal'];
      ctx.emit('navigate', { to: targets[idx] });
    },
  };

  // ----- Cleanup -----
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    // Dispose geometries & materials
    railGeo.dispose();
    railMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
    entries.forEach((e) => {
      if (e.textObject.geometry) e.textObject.geometry.dispose?.();
      if (e.textObject.material) e.textObject.material.dispose?.();
    });
  };

  return root;
}
